"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Ajanlar dört tür adımla çalışır: komut çalıştırma, dosya okuma, dosya yazma veya dosyanın bir bölümünü düzenleme. Bir komut çalışmadan ya da bir dosya değişmeden önce tam olarak ne olacağını görürsünüz ve Çalıştır (veya Uygula), Atla ya da Bu sohbette her zaman izin ver seçeneklerinden birini seçersiniz. Geçerli klasördeki dosyaları okumak onay gerektirmez.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Ajanlar yanılabilir. Çalıştırmak istediklerini okuyun, özellikle Çalışma modu veya Root ile: bu modlarda bir komut uygulamaları kaldırabilir ya da ayarları değiştirebilir.",
