"Browser Use": "Browser Use",
"Browser Use did not start the task.": "Browser Use görevi başlatmadı.",
"Browser Use failed before it had an answer.": "Browser Use, yanıt alamadan başarısız oldu.",
"Browser Use finished without an answer.": "Browser Use yanıtsız bitti.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use, açık kaynaklı tarayıcı ajanıdır; bu, yeni hesaplar için ücretsiz katmanı olan barındırılan bulutudur. Bir Ask agent düğmesi, soruyu web'de arayan kısa bir tarayıcı görevi başlatır: bir iki dakika sürebilir ve biraz kredi harcar. Yalnızca Ask agent düğmeleri içindir, sohbet değildir. Anahtarı denemek hiçbir şeye mal olmaz.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use çok uzun sürdü (4 dakikadan fazla). Daha sonra tekrar deneyin.",
"Browser Use was stopped before it had an answer.": "Browser Use, yanıt alamadan durduruldu.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Tarayıcı otomasyonu. Node ve Chromium indirmesi gerektirir; bu bir telefonda ağır olabilir.",
