"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Tema ve katmanları değiştirmek shell üzerinden yapılır. Çalışma Modları’ndan birini bağlayın, sonra geri dönün.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Tema ve katmanları değiştirmek shell üzerinden yapılır. Çalışma Modları’ndan birini bağlayın, sonra geri dönün. Şu an kullanılan renkler bu olmadan da gösterilir.",
