"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI bunun için yanıt bulamadı. Web araması'nı veya başka bir ajanı deneyin.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI, açık kaynaklı web tarayıcısıdır; bu, barındırılan bulutudur. Yeni bir hesap ücretsiz kredi ve ücretsiz aylık hak alır, kart gerekmez. Bir Ask agent düğmesi soruyu yanıt hizmetine gönderir; o da web'de arar, sayfaları okur ve yanıtı yazar. Yalnızca Ask agent düğmeleri içindir, sohbet değildir. Test bir kredi harcar.",
