"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "Listedeki uygulama simgelerini yüklediğiniz bir simge paketiyle çizin (ADW, Nova, Apex ve Go paketleri). Paketin kapsamadığı uygulamalar, varsa paketin arka planını ve şeklini alır; yoksa kendi simgelerini korur.",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind bir MCP sunucusudur: yapay zekâ ajanlarına ADB üzerinden bir Android cihazın denetimini veren bir araçtır (uygulamalar, dosyalar, günlükler, ekran görüntüleri). Kendi başına bir sohbet değildir.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind, Debian’a yüklendi. Şununla başlatın: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Ajanınıza bir MCP sunucusu olarak ekleyin (adresi başlarken yazdırılır).",
"Dry run": "Deneme çalıştırması",
