"Edit text": "Metni düzenle",
"Edited": "Düzenlenmiş",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Bir APK’yı düzenlemek içeriğini değiştirir, bu yüzden imzası artık eşleşmez. Yeniden imzalanana kadar Android onu yüklemez: “İmzala” seçeneğini kullanın (bu uygulama kendi anahtarıyla imzalar).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Bir APK’yı düzenlemek içeriğini değiştirir, bu yüzden imzası artık eşleşmez. Yeniden imzalanana kadar Android onu yüklemez; “İmzala” bunu bu uygulamanın anahtarıyla yapar.",
"Effort": "Efor",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "Efor yalnızca kendi API’sinde bu ayar bulunan ajanlar (Claude, ChatGPT, Gemini, Grok) için bir şeyi değiştirir; diğerleri için saklanır ancak API anahtarıyla sohbet ederken etkisi olmaz ve hiçbiri bunu Termux’taki kendi oturum açma aracına iletmez.",
