"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "F-Droid kataloğundaki veya bilinen herhangi bir üçüncü taraf deposundaki tüm uygulamalar. Bir depo seçin, kategoriye göre göz atın ve doğrudan yükleyin — indirmeler, deponun yayımladığı SHA-256 ile denetlenir.",
"Every app that is not enabled is saved.": "Etkin olmayan her uygulama kaydedilir.",
"Every change goes into the history, so it can be reverted.": "Her değişiklik geçmişe girer, böylece geri alınabilir.",
"Every level is hidden - tap the color key above to show some.": "Tüm düzeyler gizli - bazılarını göstermek için yukarıdaki renk anahtarına dokunun.",
