"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa bunun için bir yanıt bulamadı. Web aramasını veya başka bir ajanı deneyin.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa, yapay zeka için geliştirilmiş bir arama motorudur. Yanıt hizmeti web'de arama yapar ve kaynaklarını belirten kısa bir yanıt yazar. Yeni hesaplara ücretsiz kredi verilir. Anahtarı test etmek küçük bir arama yapar (bir kuruşun çok altında). Sor aracısı düğmesi soruyu ona gönderir; birine basana kadar hiçbir şey gönderilmez.",
