"Format": "Biçim",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Bu telefondaki uygulamanın kodundaki sınıf adları okunarak bulundu; hiçbir şey herhangi bir yere gönderilmez. İzleyici listesi: Exodus Privacy, ODbL 1.0 lisanslı. Bir küçültücü (R8, ProGuard) tarafından yeniden adlandırılan veya sonradan yüklenen kod bir izleyiciyi gizleyebilir; bu yüzden düşük bir sayı hiç olmadığının kanıtı değildir.",
