"Freeze cached apps": "Önbelleğe alınmış uygulamaları dondur",
"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "Telefonunuzdaki her uygulamayı doğrudan telefondan dondurun, debloat edin, yükleyin, yedekleyin ve inceleyin: ADB, Kablosuz hata ayıklama, Shizuku veya Root üzerinden. Bilgisayar yok, hesap yok, reklam yok.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "Dosya Yöneticisi’nden: ayrıcalıklı bir arka uç üzerinden, bu uygulamanın imza denetimleri kapalıyken yükleme. Android imzaları yine de kendisi doğrular: imzasını doğrulayamadığı bir APK bu uygulamanın anahtarıyla imzalanıp yüklenir ve başkası tarafından imzalanmış bir uygulama ancak yüklemesi kaldırıldıktan sonra değiştirilebilir (önce sorulur).",
