"Invalid source URL: the address must point to a GitHub or GitLab repository, or to a .json metadata file.": "Geçersiz kaynak URL’si: adres bir GitHub veya GitLab deposunu ya da bir .json üstveri dosyasını göstermelidir.",
"Invalid source URL: the address must start with https.": "Geçersiz kaynak URL’si: adres https ile başlamalıdır.",
