"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid (open source)": "IzzyOnDroid (açık kaynak)",
"IzzyOnDroid page": "IzzyOnDroid sayfası",
"IzzyOnDroid serves the developer's own release builds of open-source apps. The file is downloaded here.": "IzzyOnDroid, açık kaynaklı uygulamaların geliştiricinin kendi sürüm derlemelerini sunar. Dosya burada indirilir.",
"JVM code cache. Blocks of bytecode compiled into native code.": "JVM kod önbelleği. Yerel koda derlenmiş bayt kodu blokları.",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan, yapay zekâ modellerini bilgisayarınızda ücretsiz çalıştırır. Bilgisayarda: Jan, Settings, Local API Server: Host alanını 0.0.0.0 olarak ayarlayıp sunucuyu başlatın, ardından bilgisayarın adresini buraya girin (ör. http://192.168.1.20:1337/v1). Jan’ın Android sürümü yoktur.",
"Jan.ai": "Jan.ai",
"Keep": "Koru",
