"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Anahtarlar, telefonun güvenli donanımında kalan bir anahtarla şifrelenir ve yalnızca kendi sağlayıcılarının adresine gönderilir. Siz yazdıktan sonra sayfa onları bir daha asla görmez; yalnızca son dört karakter gösterilir.",
