"Let them act without asking": "Sormadan işlem yapmalarına izin ver",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Ajanın, komutun sonunda adı geçen klasörün altındaki dosyaları okumasına ve yazmasına izin verir (/sdcard yerine istediğinizi yazın).",
"Lets the agent think in explicit steps before it acts.": "Ajanın harekete geçmeden önce açık adımlar halinde düşünmesini sağlar.",
"Lets this app change a few protected system settings used by some advanced features.": "Bu uygulamanın, bazı gelişmiş özelliklerin kullandığı birkaç korumalı sistem ayarını değiştirmesine izin verir.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Bu uygulamanın, depolama alanınızdan seçtiğiniz APK, APKS ve XAPK gibi paket dosyalarını yüklemesine izin verir.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Bu uygulamanın arka plandan başka bir uygulamanın ekranını açmasına, örneğin yeni yüklediğiniz bir uygulamayı açmasına izin verir.",
