"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (cihazda)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama henüz bu telefonda çalışmıyor. Aşağıdan yükleyin veya onu çalıştıran bir bilgisayarın adresini girin.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama, bir kodlama modelini doğrudan bu telefonda çalıştırır: ücretsiz ve model indirildikten sonra çevrimdışı. Termux'a kurulur; telefonda küçük modeller (1,5B ila 3B) en iyi çalışır. Bilgisayardaki Ollama da olur: orada tüm adreslerde dinlemesini sağlayın ve bilgisayarın adresini buraya girin (192.168.1.20:11434/v1 gibi).",
"On": "Açık",
"On device": "Cihazda",
"On this phone": "Bu telefonda",
"On:": "Açık:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Her shell’de aynı anda tek bir komut çalışır; uzun çıktı ekranda ve ajana gönderilen metinde kırpılır.",
"One file only": "Yalnızca tek dosya",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Tüm uygulama için tek anahtar. Yükleyici’nin taraması ve Morphe Helper’ın taraması ikisi de bunu kullanır; hiçbiri yeniden istemez, yalnızca eksik olduğunda buraya yönlendirir.",
"One more place to find apps": "Uygulama bulmak için bir yer daha",
"One package per line. Duplicate entries are removed automatically.": "Her satıra bir paket. Yinelenen girdiler otomatik olarak kaldırılır.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Bir kaynak renk, onu bütün bir temaya dönüştürmenin dokuz yolu: açık ve koyu modda vurgu, arka plan, kartlar ve metin. Bir stil seçmek, temayı aşağıdaki kaynak renkten oluşturur.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Yalnızca AppCleaner kullanır: hiçbir dosya erişiminin ulaşamadığı önbellekler için her uygulamanın sistem Uygulama bilgisi ekranını açar ve Önbelleği temizle’ye dokunur. Başka hiçbir şey yapmaz, bu ekranlar dışında ekrandakileri asla okumaz ve ekran kapanınca durur.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "Bu dosyalara yalnızca işaretli bir blok yazılır; içlerindeki mevcut içerik kalır ve bunu yeniden çalıştırmak yeni bir blok eklemek yerine bloğu yeniler.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Yalnızca güvendiğiniz kaynakları ekleyin. Bir yama kaynağı, yamalı uygulamalarınızın içine neyin gireceğine karar verir.",
"Only apps installed on this phone": "Yalnızca bu telefonda yüklü uygulamalar",
"Only base": "Yalnızca ana APK",
"Only hidden files are here. Tick Show hidden files to see them.": "Burada yalnızca gizli dosyalar var. Görmek için Gizli dosyaları göster’i işaretleyin.",
"Only include common media files, documents and archives.": "Yalnızca yaygın medya dosyalarını, belgeleri ve arşivleri dahil et.",
"Only list what would run for each app. Nothing is run.": "Her uygulama için yalnızca çalıştırılacakları listeler. Hiçbir şey çalıştırılmaz.",
"Only patches for apps installed on this phone": "Yalnızca bu telefonda yüklü uygulamaların yamaları",
"Only split bundles are listed for this app. Turn on Allow split APK.": "Bu uygulama için yalnızca bölünmüş paketler listeleniyor. Split APK'ya izin ver seçeneğini açın.",
"Only text and compiled XML files can be compared line by line": "Yalnızca metin ve derlenmiş XML dosyaları satır satır karşılaştırılabilir",
"Only the app name you typed is sent.": "Yalnızca yazdığınız uygulama adı gönderilir.",
"Only the lines written by the app you pick": "Yalnızca seçtiğiniz uygulamanın yazdığı satırlar",
"Only the selected apps are saved.": "Yalnızca seçili uygulamalar kaydedilir.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Yalnızca bu uygulamanın metni değişir; kod kutularındaki adlar, yollar ve komutlar kendi yazı tipini korur.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "Ona yalnızca bu örnek soru gönderilir: Hesap Makinesi paketinin devre dışı bırakılıp bırakılamayacağı.",
