"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "MCP düğmesi, Model Context Protocol aracılığıyla bir ajana ek araçlar (dosyalar, web, bir tarayıcı, GitHub...) vermek için bir alt sayfa açar. Hazır bir ayar seçin veya kendiniz yazın: bir ad, bir yerel komut veya uzak bir adres ve gereken anahtar ya da başlık. Hangi ajanlara ekleneceğini seçin — her ajan bunu kendi dosyasında tuttuğu için aynı sunucu aynı anda iki veya daha fazla ajana eklenebilir.",
"The Morphe engine is not in this build of the app": "Morphe motoru uygulamanın bu sürümünde yok",
"The PDF could not be shown.": "PDF gösterilemedi.",
"The Play Store gives no download to other apps. This opens the app's page in the Play Store.": "Play Store diğer uygulamalara indirme vermez. Bu, uygulamanın Play Store'daki sayfasını açar.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Rish shell’i sona erdi. Yeni bir tane açmak için “Rish modu” düğmesine dokunun.",
"The Rish shell is no longer running.": "Rish shell’i artık çalışmıyor.",
"The Terminal needs the app (it is not available in a plain browser)": "Terminal için uygulama gerekir (sıradan bir tarayıcıda kullanılamaz)",
"The UAD-NG list has not been downloaded yet.": "UAD-NG listesi henüz indirilmedi.",
"The UAD-NG list has nothing on this app": "UAD-NG listesinde bu uygulama hakkında bir şey yok",
"The VirusTotal scan did not work": "VirusTotal taraması çalışmadı",
"The VirusTotal scan did not work.": "VirusTotal taraması çalışmadı.",
"The accessibility service is not ready": "Erişilebilirlik hizmeti hazır değil",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Erişilebilirlik hizmeti hazır değil (bağlı değil), bu yüzden yalnızca onun temizleyebildiği önbellekler kalır. Bundan sonra AppCleaner kartındaki “Kalanı erişilebilirlikle temizle” seçeneğini kullanın.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Erişilebilirlik hizmeti hazır değil (kapalı), bu yüzden yalnızca onun temizleyebildiği önbellekler kalır. Bundan sonra AppCleaner kartındaki “Kalanı erişilebilirlikle temizle” seçeneğini kullanın.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "Erişilebilirlik hizmeti hazır değil (izin verilmedi), bu yüzden yalnızca onun temizleyebildiği önbellekler kalır. Bundan sonra AppCleaner kartındaki “Kalanı erişilebilirlikle temizle” seçeneğini kullanın.",
"The account has no credit left, or a spending limit was reached.": "Hesapta kredi kalmadı ya da bir harcama sınırına ulaşıldı.",
"The agent is still working: STOP it first": "Ajan hâlâ çalışıyor: önce STOP ile durdurun",
"The agent pauses after this many steps.": "Ajan bu kadar adımdan sonra duraklar.",
"The app": "Uygulama",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "Uygulama ücretsiz ve öyle kalacak. Size zaman kazandırdıysa, bir kahve onu geliştirmeye devam etmeme yardımcı olur. Tamamen isteğe bağlı, teşekkürler!",
"The app version, Android version and phone model, so a problem is easier to find.": "Bir sorunun bulunmasını kolaylaştırmak için uygulama sürümü, Android sürümü ve telefon modeli.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Yamaladığınız uygulamalar, her çalıştırmanın günlüğüyle birlikte burada listelenir; böylece onları yeniden yükleyebilir, paylaşabilir veya İndirilenler’e kaydedebilirsiniz.",
"The archive file is rewritten without this file.": "Arşiv dosyası bu dosya olmadan yeniden yazılır.",
"The archive file is rewritten without this folder and everything in it.": "Arşiv dosyası bu klasör ve içindeki her şey olmadan yeniden yazılır.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "Arşiv, yalnızca tüm dosyaları atlanan olmadan çıkarıldığında silinir.",
