"The list of fonts is cleared": "Yazı tipi listesi temizlendi",
"The lists are cut at 3000 entries each.": "Listeler her biri 3000 girdide kesilir.",
"The manifest does not ask for any extra library (no uses-library entry).": "Manifest herhangi bir ek kitaplık istemiyor (uses-library girdisi yok).",
"The name in code type is the key. It is the same on every phone that has the setting.": "Kod türündeki ad anahtardır. Ayarın bulunduğu her telefonda aynıdır.",
"The old code is gone. Anything you gave it to has to be given the new one.": "Eski kod artık yok. Onu verdiğiniz her şeye yeni kod verilmelidir.",
"The older storage permission some apps still check for.": "Bazı uygulamaların hâlâ kontrol ettiği eski depolama izni.",
"The pairing code has 6 digits": "Eşleme kodu 6 haneden oluşur",
"The password is used only for this archive, only while it is open. It is never saved.": "Bu şifre yalnızca bu arşiv için, yalnızca açık olduğu sürece kullanılır. Hiçbir zaman kaydedilmez.",
"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "Yama paketi hasarlı olabilir veya daha yeni bir Morphe için yapılmış olabilir. Kaynaklar’dan kaynağı güncelleyin.",
"The patched APK is only saved. Install it from Patched APKs.": "Yamalı APK yalnızca kaydedilir. Yamalı APK’lar bölümünden yükleyin.",
