"The patcher could not be started": "Yamalayıcı başlatılamadı",
"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Yamalayıcının belleği bitti. Diğer uygulamaları kapatıp yeniden deneyin veya yamalayıcı ayarlarında “Kullanılmayan yerel kitaplıkları ayıkla”yı açın.",
"The patcher stopped": "Yamalayıcı durdu",
"The patcher stops and nothing is saved.": "Yamalayıcı durur ve hiçbir şey kaydedilmez.",
"The patches could not be read": "Yamalar okunamadı",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Yamalar uygulamanın bu sürümünü desteklemiyor. Morphe Helper ile desteklenen bir sürüm edinin veya yamalayıcı ayarlarında “Desteklenmeyen sürümleri yamala”yı açın.",
"The paths could not be read.": "Yollar okunamadı.",
"The phone may still apply it. It is looked at again in a moment.": "Telefon yine de uygulayabilir. Birazdan yeniden bakılır.",
"The phone may still apply it. The list is read again in a moment.": "Telefon yine de uygulayabilir. Liste birazdan yeniden okunur.",
"The phone's browser": "Telefonun tarayıcısı",
"The project gives no description for this package.": "Proje bu paket için bir açıklama vermiyor.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Sağlayıcılar Android’i resmî olarak desteklemiyor: araç her telefonda çalışmayabilir. Bir sorun olduğunda Terminal, aracın iletilerini olduğu gibi gösterir.",
"The pull did not finish": "Çekme işlemi tamamlanmadı",
"The push did not finish": "Gönderme işlemi tamamlanmadı",
"The quick brown fox jumps over the lazy dog.": "The quick brown fox jumps over the lazy dog.",
"The repository must be an https:// address": "Depo bir https:// adresi olmalıdır",
"The request could not be sent": "İstek gönderilemedi",
"The request could not start": "İstek başlatılamadı",
"The research agent behind every Ask agent button, and the one the Application Updater asks to find an app. It reads the web and weighs what it finds to answer: what a hidden setting, a permission, a process, a log line or an app is. It is not a coding agent and it never changes anything on the phone. Perplexity is the default: it searches the web by itself and names its sources. Its key is set up in the Command-Line Interface tab.": "Her Sor aracısı düğmesinin arkasındaki ve Uygulama Güncelleyici'nin bir uygulamayı bulmak için sorduğu araştırma aracısı. Web'i okur ve bulduklarını tartarak şunun yanıtını verir: gizli bir ayar, bir izin, bir işlem, bir günlük satırı veya bir uygulama nedir. Kodlama aracısı değildir ve telefonda hiçbir şeyi değiştirmez. Varsayılan Perplexity'dir: web'i kendisi arar ve kaynaklarını belirtir. Anahtarı Komut Satırı Arayüzü sekmesinde ayarlanır.",
"The resolution the device draws at, width x height in pixels.": "Cihazın çizim yaptığı çözünürlük, piksel cinsinden genişlik x yükseklik.",
"The round checkmark button (when apps are selected)": "Yuvarlak onay işareti düğmesi (uygulamalar seçiliyken)",
"The scan failed: unknown error": "Tarama başarısız oldu: bilinmeyen hata",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "Dosyaların ulaşamadığı bir önbelleği hâlâ olan her uygulama için Önbelleği temizle’ye dokunulurken ekranda bir an için sırayla her uygulamanın ayarları görünür. Bir örtü ne olduğunu gösterir ve İptal düğmesi vardır. Ekran kapanırsa durur.",
"The search could not start": "Arama başlatılamadı",
