"The search failed": "Arama başarısız oldu",
"The search failed.": "Arama başarısız oldu.",
"The search failed: unknown error": "Arama başarısız oldu: bilinmeyen hata",
"The search took too long. Tap Find APKs to try again.": "Arama çok uzun sürdü. Yeniden denemek için “APK’ları bul” düğmesine dokunun.",
"The service is off.": "Hizmet kapalı.",
"The service is switched on but has not connected yet; turn it off and on again in the accessibility settings.": "Hizmet açık ama henüz bağlanmadı; erişilebilirlik ayarlarından kapatıp yeniden açın.",
"The setting's name, table and current value are sent to them.": "Ayarın adı, tablosu ve geçerli değeri onlara gönderilir.",
"The shell did not start": "Shell başlamadı",
"The signing key that apps patched or re-signed here are signed with. Export it to keep a copy, and import it on another phone, so those apps keep updating in place.": "Burada yamalanan veya yeniden imzalanan uygulamaların imzalandığı imzalama anahtarı. Bir kopyasını saklamak için dışa aktarın, başka bir telefonda içe aktarın; böylece bu uygulamalar yerinde güncellenmeye devam eder.",
"The small messages while a change is made and checked": "Bir değişiklik yapılıp denetlenirken görünen küçük iletiler",
"The source could not be added": "Kaynak eklenemedi",
"The sources that are on do not have patches yet, or the patch engine could not read them. Open Sources to update them.": "Açık kaynakların henüz yaması yok ya da yama motoru onları okuyamadı. Güncellemek için Kaynaklar’ı açın.",
