"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Ardından bu uygulamaya “Run commands in Termux environment” izni verin ve bağlantıyı test edin. Terminal ayarlarındaki Termux kurulumu size adım adım yol gösterir.",
"There are no saved lists to back up yet": "Yedeklenecek kayıtlı liste henüz yok",
