"These apps are currently selected for this action:": "Bu işlem için şu anda şu uygulamalar seçili:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Bu uygulamalar kaldırılmış ama veri klasörleri hâlâ telefonda. İşaretlediğiniz uygulamaların verileri kalıcı olarak silinir.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Bu uygulamalar kaldırılmış. Root olmadan uygulama hangilerinin hâlâ verisi olduğunu göremez; bu yüzden hepsini temizlemek güvenlidir ama bazıları için bir şey bulamayabilir. İşaretlediğiniz uygulamaların verileri kalıcı olarak silinir.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Bu uygulamaların sürümleri, bu uygulamanın doğrudan denetleyemediği sitelerde yayımlanıyor. Obtainium bunları izleyebilir.",
"These files are too different to compare line by line. View each one instead.": "Bu dosyalar satır satır karşılaştırılamayacak kadar farklı. Bunun yerine her birini görüntüleyin.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Tarayıcı kapatılınca sürerler. Duraklat, indirileni korur; Sürdür yalnızca kalanı siteden ister (bunu yapamayan bir site dosyayı baştan başlatır).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Yine de yamalamazsanız atlanırlar; bu başarısız olabilir veya uygulamayı bozabilir.",
