"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Bu uygulama belirli bir dokunmatik ekran, klavye veya gezinme istemiyor (uses-configuration girdisi yok), bu yüzden bu telefonda ne varsa onunla çalışır.",
