"This app now has its own private ADB key. Tap the mode badge for details.": "Bu uygulamanın artık kendine ait özel bir ADB anahtarı var. Ayrıntılar için mod rozetine dokunun.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Bu uygulamanın kodu okunamadı (kodu yok ya da dosya okunamıyor), bu yüzden izleyiciler hakkında bir şey söylenemez.",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "Bu uygulamanın kendi yetkilendirme kodu. Henüz hiçbir şey kabul etmiyor: sonrası için burada saklanıyor. Bu telefonda oluşturulur, bu telefonda kalır ve istediğiniz zaman değiştirebilirsiniz.",
