"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Yinelenenleri silerken SD Maid, her ölçütü sırayla denetleyerek hangi dosyayı tutacağına karar verir. Net bir kazanan çıkaran ilk ölçüt sonucu belirler. Yeniden sıralamak için sürükleyin, modu değiştirmek için dokunun.",
