"Without it AppCleaner still deletes every cache it can reach with file access and, with a working mode, trims the caches of all apps at once.": "Bu olmadan AppCleaner yine dosya erişimiyle ulaşabildiği her önbelleği siler ve bir çalışma moduyla tüm uygulamaların önbelleklerini bir seferde kırpar.",
