"You can grant or revoke it here.": "Bunu buradan verebilir veya iptal edebilirsiniz.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Bu APK’yı düzenlediniz, bu yüzden imzası artık geçerli değil ve Android onu olduğu gibi yüklemez.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Bir Android gizli ayarını (Settings.Global, Settings.Secure veya Settings.System veritabanının bir girdisi, “settings get/put”un okuduğu ve yazdığı türden) geliştirici olmayan birine açıklıyorsunuz.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Bir Android gizli ayarını (Settings.Global, Settings.Secure veya Settings.System veritabanının bir girdisi, “settings get/put”un okuduğu ve yazdığı türden) geliştirici olmayan birine açıklıyorsunuz. Kısaca söyleyin: neyi denetlediğini, değerlerinin ne anlama geldiğini, değiştirmenin ne yaptığını ve değiştirmenin güvenli olup olmadığını. Ayarı bilmiyorsanız (çoğu telefon üreticisine aittir) tahmin etmek yerine bunu açıkça söyleyin, sonra adının ne düşündürdüğünü söyleyin. Kısa paragraflar, başlık yok.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Bir Android logcat girdisini geliştirici olmayan birine açıklıyorsunuz. Sade sözlerle ve kısaca söyleyin: bu satırın ne anlama geldiğini,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Bir Android logcat girdisini geliştirici olmayan birine açıklıyorsunuz. Sade sözlerle ve kısaca söyleyin: bu satırın ne anlama geldiğini, en olası nedeni, önemli olup olmadığını (zararsız gürültü, gerçek bir sorun veya bir çökme) ve önemliyse neyin denenebileceğini. Kısa paragraflar kullanın, başlık yok. Satır güvenle açıklanamayacak kadar anlaşılmazsa bunu söyleyin ve başka neyin yardımcı olacağını belirtin. Ayrıntı uydurmayın.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Android terminalinde ADB ve shell komut sözdizimi konusunda yardımcı oluyorsun. Kısa ve pratik yanıt ver.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Android terminalinde ADB ve shell komut sözdizimi konusunda yardımcı oluyorsun. Kısa ve pratik yanıt ver. Kullanıcının burada çalıştırması için tam olarak bir komut önermek istiyorsan, onu tek başına şunun içine koy",
